const a=[{id:"analyzers-001",topicId:"analyzers",question:"Что такое анализатор (сенсорная система)?",options:["Совокупность желёз внутренней секреции","Специализированная часть нервной системы, отвечающая за восприятие информации и формирование ответа на раздражение","Часть мышечной системы, обеспечивающая движение","Отдельный орган чувств без связи с мозгом"],correctIndex:1,explanation:"Анализатор — специализированная часть нервной системы, отвечающая за восприятие информации и формирование ответа на раздражение.",difficulty:"easy",tags:["анализаторы","определения"]},{id:"analyzers-002",topicId:"analyzers",question:"Сколько отделов выделяют в каждом анализаторе?",options:["Пять","Четыре","Три","Два"],correctIndex:2,explanation:"В каждом анализаторе три отдела: периферический, проводниковый и центральный.",difficulty:"easy",tags:["анализаторы"]},{id:"analyzers-003",topicId:"analyzers",question:"Какой отдел анализатора воспринимает информацию и преобразует энергию раздражителя в нервный импульс?",options:["Вегетативный","Проводниковый","Центральный","Периферический"],correctIndex:3,explanation:"В периферическом отделе происходит восприятие информации и преобразование энергии раздражителя в нервный импульс.",difficulty:"medium",tags:["анализаторы","отделы"]},{id:"analyzers-004",topicId:"analyzers",question:"Какова функция проводникового отдела анализатора?",options:["Преобразует энергию раздражителя в импульс","Вырабатывает гормоны","Обрабатывает информацию и формирует ответ","Передаёт импульс в центральный отдел"],correctIndex:3,explanation:"Проводниковый отдел передаёт нервный импульс в центральный отдел анализатора.",difficulty:"medium",tags:["анализаторы","отделы"]},{id:"analyzers-005",topicId:"analyzers",question:"Какой отдел анализатора отвечает за обработку информации и формирование ответа?",options:["Рецепторный","Проводниковый","Периферический","Центральный"],correctIndex:3,explanation:"Центральный отдел анализатора обрабатывает информацию и формирует ответ.",difficulty:"medium",tags:["анализаторы","отделы"]},{id:"analyzers-006",topicId:"analyzers",question:"Что является периферическим отделом зрительного анализатора?",options:["Затылочная доля коры","Зрительный нерв","Глаз","Средний мозг"],correctIndex:2,explanation:"Периферический отдел зрительного анализатора — глаз.",difficulty:"easy",tags:["зрение","отделы"]},{id:"analyzers-007",topicId:"analyzers",question:"Где расположен центральный отдел зрительного анализатора?",options:["В теменной доле коры","В лобной доле коры","В височной доле коры","В затылочной доле коры больших полушарий"],correctIndex:3,explanation:"Центральный отдел зрительного анализатора — затылочная доля коры больших полушарий.",difficulty:"medium",tags:["зрение","кора мозга"]},{id:"analyzers-008",topicId:"analyzers",question:"Что относится к вспомогательному аппарату глаза?",options:["Склера, роговица и сетчатка","Хрусталик и стекловидное тело","Брови, ресницы, веки, слёзный аппарат и мышцы","Радужка и ресничное тело"],correctIndex:2,explanation:"Вспомогательный аппарат глаза — брови, ресницы и веки, слёзный аппарат и мышцы.",difficulty:"medium",tags:["зрение","анатомия"]},{id:"analyzers-009",topicId:"analyzers",question:"Сколько оболочек имеет глазное яблоко?",options:["Три: наружную, сосудистую и внутреннюю (сетчатку)","Две: наружную и внутреннюю","Четыре: склеру, роговицу, радужку и сетчатку","Одну — склеру"],correctIndex:0,explanation:"Глазное яблоко имеет три оболочки: наружную, сосудистую и внутреннюю (сетчатку).",difficulty:"easy",tags:["зрение","анатомия"]},{id:"analyzers-010",topicId:"analyzers",question:"Из чего состоит наружная оболочка глаза?",options:["Из сетчатки и пигментного эпителия","Из радужки и ресничного тела","Из склеры (белочной оболочки) и прозрачной роговицы","Из хрусталика и стекловидного тела"],correctIndex:2,explanation:"Наружная оболочка глаза состоит из склеры (белочной) и прозрачной роговицы.",difficulty:"medium",tags:["зрение","анатомия"]},{id:"analyzers-011",topicId:"analyzers",question:"Чем спереди покрыта наружная оболочка глаза?",options:["Надкостницей","Сетчаткой","Конъюнктивой","Синовиальной оболочкой"],correctIndex:2,explanation:"Спереди наружная оболочка глаза покрыта конъюнктивой.",difficulty:"medium",tags:["зрение","анатомия"]},{id:"analyzers-012",topicId:"analyzers",question:"Какие три части имеет сосудистая оболочка глаза?",options:["Хрусталик, зрачок и стекловидное тело","Радужку, ресничное тело и собственно сосудистую оболочку","Склеру, роговицу и конъюнктиву","Палочки, колбочки и пигментный слой"],correctIndex:1,explanation:"Сосудистая оболочка имеет переднюю часть (радужку), среднюю (ресничное тело) и заднюю (собственно сосудистую оболочку).",difficulty:"hard",tags:["зрение","анатомия"]},{id:"analyzers-013",topicId:"analyzers",question:"Какова функция зрачка?",options:["Вырабатывает водянистую влагу","Регулирует количество света, поступающего на хрусталик","Фокусирует лучи на сетчатке","Воспринимает цвет"],correctIndex:1,explanation:"Зрачок — отверстие в радужке, регулирующее количество света, поступающего на хрусталик.",difficulty:"easy",tags:["зрение","физиология"]},{id:"analyzers-014",topicId:"analyzers",question:"Что представляет собой хрусталик?",options:["Прозрачное аморфное вещество за сетчаткой","Двояковыпуклую линзу, преломляющую и фокусирующую лучи на сетчатке","Слой фоторецепторов","Отверстие в радужке"],correctIndex:1,explanation:"Хрусталик — двояковыпуклая линза за радужкой, преломляющая и фокусирующая лучи на сетчатке.",difficulty:"easy",tags:["зрение","анатомия"]},{id:"analyzers-015",topicId:"analyzers",question:"Что расположено позади хрусталика?",options:["Радужка","Роговица","Конъюнктива","Стекловидное тело"],correctIndex:3,explanation:"За хрусталиком расположено стекловидное тело — прозрачное аморфное вещество.",difficulty:"medium",tags:["зрение","анатомия"]},{id:"analyzers-016",topicId:"analyzers",question:"Какой зрительный пигмент содержат палочки сетчатки?",options:["Меланин","Гемоглобин","Йодопсин","Родопсин"],correctIndex:3,explanation:"Палочки содержат родопсин и отвечают за сумеречное зрение.",difficulty:"medium",tags:["зрение","сетчатка"]},{id:"analyzers-017",topicId:"analyzers",question:"За какое зрение отвечают колбочки?",options:["За сумеречное зрение","За цветное зрение","За аккомодацию","За бинокулярное слияние изображений"],correctIndex:1,explanation:"Колбочки содержат йодопсин и отвечают за цветное зрение.",difficulty:"medium",tags:["зрение","сетчатка"]},{id:"analyzers-018",topicId:"analyzers",question:"Какие фоторецепторы отвечают за сумеречное зрение?",options:["Пигментные клетки","Колбочки","Волосковые клетки","Палочки"],correctIndex:3,explanation:"За сумеречное зрение отвечают палочки, содержащие родопсин.",difficulty:"medium",tags:["зрение","сетчатка"]},{id:"analyzers-019",topicId:"analyzers",question:"Какое изображение формируется на сетчатке?",options:["Прямое и увеличенное","Перевёрнутое и уменьшенное","Прямое и уменьшенное","Перевёрнутое и увеличенное"],correctIndex:1,explanation:"На сетчатке формируется перевёрнутое и уменьшенное изображение.",difficulty:"medium",tags:["зрение","физиология"]},{id:"analyzers-020",topicId:"analyzers",question:"Как называется адаптация глаза к ясному видению предметов, удалённых на разные расстояния?",options:["Конвергенция","Аккомодация","Адаптация к темноте","Рефракция"],correctIndex:1,explanation:"Адаптация глаза к ясному видению предметов на разных расстояниях называется аккомодацией.",difficulty:"easy",tags:["зрение","физиология"]},{id:"analyzers-021",topicId:"analyzers",question:"Какой вид зрения характерен для человека согласно лекции?",options:["Только периферическое","Монокулярное и чёрно-белое","Бинокулярное и цветное","Только сумеречное"],correctIndex:2,explanation:"Для человека характерно бинокулярное и цветное зрение.",difficulty:"easy",tags:["зрение"]},{id:"analyzers-022",topicId:"analyzers",question:"Какова правильная последовательность прохождения света в глазу?",options:["Роговица → хрусталик → зрачок → сетчатка → стекловидное тело","Хрусталик → роговица → зрачок → сетчатка → стекловидное тело","Зрачок → роговица → стекловидное тело → хрусталик → сетчатка","Роговица → зрачок → хрусталик → стекловидное тело → сетчатка"],correctIndex:3,explanation:"Свет проходит через роговицу, зрачок, хрусталик (фокусировка), стекловидное тело и попадает на нейроны и фоторецепторы сетчатки.",difficulty:"hard",tags:["зрение","физиология"]},{id:"analyzers-023",topicId:"analyzers",question:"Куда идёт импульс по зрительному нерву перед тем, как достичь затылочной доли коры (по схеме лекции)?",options:["В спинной мозг","В средний мозг","В продолговатый мозг","В мозжечок"],correctIndex:1,explanation:"По схеме зрительного восприятия импульс идёт по зрительному нерву в средний мозг, а затем в затылочную долю коры.",difficulty:"hard",tags:["зрение","проводящие пути"]},{id:"analyzers-024",topicId:"analyzers",question:"Где фокусируются лучи при дальнозоркости?",options:["До сетчатки","На роговице","Точно на сетчатке","За сетчаткой"],correctIndex:3,explanation:"При дальнозоркости лучи фокусируются за сетчаткой, поэтому близкие предметы видны хуже удалённых.",difficulty:"medium",tags:["зрение","нарушения зрения"]},{id:"analyzers-025",topicId:"analyzers",question:"Как видит человек с близорукостью?",options:["Близкие предметы хуже, чем удалённые","Удалённые предметы хуже, чем близко расположенные","Плохо видит в сумерках","Не различает цвета"],correctIndex:1,explanation:"При близорукости человек видит удалённые предметы хуже, чем близко расположенные; лучи фокусируются до сетчатки.",difficulty:"medium",tags:["зрение","нарушения зрения"]},{id:"analyzers-026",topicId:"analyzers",question:"Что такое глаукома?",options:["Отслойка сетчатки","Воспаление конъюнктивы","Помутнение хрусталика","Повышение внутриглазного давления из-за нарушения оттока водянистой влаги"],correctIndex:3,explanation:"Глаукома — повышение внутриглазного давления из-за нарушения оттока водянистой влаги; может привести к слепоте.",difficulty:"medium",tags:["зрение","заболевания"]},{id:"analyzers-027",topicId:"analyzers",question:"Что такое катаракта?",options:["Повышение внутриглазного давления","Искривление роговицы","Частичное или полное помутнение хрусталика","Воспаление роговицы"],correctIndex:2,explanation:"Катаракта — частичное или полное помутнение хрусталика, проявляется снижением остроты зрения, чувством пелены или тумана.",difficulty:"easy",tags:["зрение","заболевания"]},{id:"analyzers-028",topicId:"analyzers",question:"Что названо причинами катаракты в лекции?",options:["Бактериальная инфекция роговицы","Старение организма и нарушение обменных процессов","Травма барабанной перепонки","Повышенное внутриглазное давление"],correctIndex:1,explanation:"Причины катаракты — старение организма и нарушение обменных процессов.",difficulty:"medium",tags:["зрение","заболевания"]},{id:"analyzers-029",topicId:"analyzers",question:"Какой антибиотик входит в состав комбинированных глазных капель вместе с дексаметазоном?",options:["Левомицетин","Тобрамицин","Тетрациклин","Левофлоксацин"],correctIndex:1,explanation:"В таблице глазных препаратов указана комбинация дексаметазон + тобрамицин.",difficulty:"hard",tags:["препараты","офтальмология"]},{id:"analyzers-030",topicId:"analyzers",question:"С каким веществом комбинируется бринзоламид в глазных препаратах из лекции?",options:["С цитиколином","С кетотифеном","С тимололом","С дексаметазоном"],correctIndex:2,explanation:"В лекции указана комбинация бринзоламид + тимолол.",difficulty:"hard",tags:["препараты","офтальмология"]},{id:"analyzers-031",topicId:"analyzers",question:"Какое вещество комбинируется с гиалуроновой кислотой в глазном препарате из таблицы?",options:["Тимолол","Тобрамицин","Цитиколин","Преднизолон"],correctIndex:2,explanation:"В таблице глазных препаратов указана комбинация гиалурон + цитиколин.",difficulty:"hard",tags:["препараты","офтальмология"]},{id:"analyzers-032",topicId:"analyzers",question:"Какой орган выполняет роль периферического отдела в слуховой сенсорной системе?",options:["Евстахиева труба","Преддверно-улитковый нерв","Ухо","Височная доля коры"],correctIndex:2,explanation:"Периферический отдел слухового анализатора — ухо.",difficulty:"easy",tags:["слух","отделы"]},{id:"analyzers-033",topicId:"analyzers",question:"Какой нерв является проводниковым отделом слухового анализатора?",options:["Лицевой","Языкоглоточный","Преддверно-улитковый","Тройничный"],correctIndex:2,explanation:"Проводниковый отдел слухового анализатора — преддверно-улитковый нерв.",difficulty:"medium",tags:["слух","отделы"]},{id:"analyzers-034",topicId:"analyzers",question:"Какая доля коры обрабатывает слуховую информацию?",options:["В мозжечке","В теменной доле коры","В височной доле коры больших полушарий","В затылочной доле коры"],correctIndex:2,explanation:"Центральный отдел слухового анализатора — височная доля коры больших полушарий.",difficulty:"medium",tags:["слух","кора мозга"]},{id:"analyzers-035",topicId:"analyzers",question:"Чем представлено наружное ухо?",options:["Евстахиевой трубой и носоглоткой","Ушной раковиной, слуховым проходом и барабанной перепонкой","Барабанной полостью и слуховыми косточками","Улиткой и полукружными каналами"],correctIndex:1,explanation:"Наружное ухо представлено ушной раковиной, слуховым проходом и барабанной перепонкой; в нём есть железы ушной серы.",difficulty:"easy",tags:["слух","анатомия"]},{id:"analyzers-036",topicId:"analyzers",question:"Какова функция наружного уха?",options:["Усиление звуковых колебаний косточками","Улавливание звуков и их передача в среднее ухо","Восприятие положения тела в пространстве","Преобразование звука в нервный импульс"],correctIndex:1,explanation:"Функция наружного уха — улавливание звуков и их передача в среднее ухо.",difficulty:"medium",tags:["слух","физиология"]},{id:"analyzers-037",topicId:"analyzers",question:"В какой кости расположено среднее ухо?",options:["В клиновидной","В затылочной","В теменной","В височной"],correctIndex:3,explanation:"Среднее ухо находится в височной кости.",difficulty:"medium",tags:["слух","анатомия"]},{id:"analyzers-038",topicId:"analyzers",question:"Какие слуховые косточки находятся в барабанной полости?",options:["Молоточек, наковальня и стремечко","Молоточек, улитка и стремечко","Наковальня, отолиты и преддверие","Стремечко, мешочек и маточка"],correctIndex:0,explanation:"В барабанной полости находятся 3 слуховые косточки: молоточек, наковальня, стремечко.",difficulty:"easy",tags:["слух","анатомия"]},{id:"analyzers-039",topicId:"analyzers",question:"Какова функция слуховых косточек?",options:["Соединяют ухо с носоглоткой","Воспринимают положение тела","Вырабатывают ушную серу","Передают и усиливают звуковые колебания"],correctIndex:3,explanation:"Слуховые косточки передают и усиливают звуковые колебания.",difficulty:"medium",tags:["слух","физиология"]},{id:"analyzers-040",topicId:"analyzers",question:"С помощью какой структуры барабанная полость связана с носоглоткой?",options:["Улитки","Евстахиевой (слуховой) трубы","Полукружных каналов","Наружного слухового прохода"],correctIndex:1,explanation:"Барабанная полость связана с носоглоткой с помощью евстахиевой трубы.",difficulty:"easy",tags:["слух","анатомия"]},{id:"analyzers-041",topicId:"analyzers",question:"Из каких лабиринтов состоит внутреннее ухо?",options:["Из перепончатого и жирового","Из костного и хрящевого","Из костного и перепончатого","Из хрящевого и мышечного"],correctIndex:2,explanation:"Внутреннее ухо находится в височной кости и состоит из костного и перепончатого лабиринта.",difficulty:"medium",tags:["слух","анатомия"]},{id:"analyzers-042",topicId:"analyzers",question:"Какие три отдела выделяют в лабиринтах внутреннего уха?",options:["Молоточек, наковальню и стремечко","Ушную раковину, слуховой проход и перепонку","Барабанную полость, евстахиеву трубу и улитку","Преддверие, улитку и три полукружных канала"],correctIndex:3,explanation:"В лабиринтах три отдела: преддверие, улитка и три взаимоперпендикулярных полукружных канала.",difficulty:"medium",tags:["слух","анатомия"]},{id:"analyzers-043",topicId:"analyzers",question:"Где расположены слуховые рецепторы (волосковые клетки)?",options:["В наружном слуховом проходе","В барабанной полости","В улитке","В полукружных каналах"],correctIndex:2,explanation:"Слуховые рецепторы (волосковые клетки) находятся в улитке, а в полукружных каналах — вестибулярные рецепторы.",difficulty:"medium",tags:["слух","рецепторы"]},{id:"analyzers-044",topicId:"analyzers",question:"Как расположены полукружные каналы относительно друг друга?",options:["Концентрически","Взаимоперпендикулярно","Последовательно в одну линию","Параллельно"],correctIndex:1,explanation:"Три полукружных канала внутреннего уха взаимоперпендикулярны.",difficulty:"hard",tags:["слух","вестибулярный аппарат"]},{id:"analyzers-045",topicId:"analyzers",question:"С каким веществом комбинируется феназон в ушных каплях при отите?",options:["С лидокаином","С рифамицином","С неомицином","С гидрокортизоном"],correctIndex:0,explanation:"В таблице препаратов при отите указана комбинация феназон + лидокаин.",difficulty:"hard",tags:["препараты","отит"]},{id:"analyzers-046",topicId:"analyzers",question:"Какой антибиотик входит в комбинацию с гидрокортизоном и лидокаином в ушных каплях?",options:["Тобрамицин","Рифамицин","Неомицин","Тетрациклин"],correctIndex:2,explanation:"В таблице препаратов при отите указана комбинация неомицин + гидрокортизон + лидокаин.",difficulty:"hard",tags:["препараты","отит"]},{id:"analyzers-047",topicId:"analyzers",question:"Что воспринимает вестибулярный аппарат?",options:["Звуковые колебания","Вкус пищи","Температуру окружающей среды","Движения и положение организма в пространстве"],correctIndex:3,explanation:"Вестибулярный аппарат воспринимает движения и положения организма в пространстве.",difficulty:"easy",tags:["вестибулярный аппарат"]},{id:"analyzers-048",topicId:"analyzers",question:"Как называются камешки, примыкающие к рецепторам вестибулярного аппарата?",options:["Отолиты","Остеоны","Конкременты","Ацинусы"],correctIndex:0,explanation:"В полукружных каналах есть рецепторы с примыкающими к ним камешками — отолитами.",difficulty:"medium",tags:["вестибулярный аппарат"]},{id:"analyzers-049",topicId:"analyzers",question:"Куда идёт импульс от рецепторов вестибулярного аппарата?",options:["В спинной мозг и мозжечок","В промежуточный мозг и большие полушария","Только в продолговатый мозг","В симпатический ствол"],correctIndex:1,explanation:"Возникший в вестибулярном аппарате импульс идёт в промежуточный мозг и большие полушария.",difficulty:"hard",tags:["вестибулярный аппарат","проводящие пути"]},{id:"analyzers-050",topicId:"analyzers",question:"С каких структур начинается восприятие запахов?",options:["Обонятельные рецепторы","Вкусовые почки","Височная доля коры","Обонятельный нерв"],correctIndex:0,explanation:"Периферический отдел обонятельного анализатора — обонятельные рецепторы.",difficulty:"easy",tags:["обоняние","отделы"]},{id:"analyzers-051",topicId:"analyzers",question:"Какой участок коры больших полушарий отвечает за анализ запахов?",options:["В затылочной доле коры","В мозжечке","На нижней поверхности височной доли коры","В теменной доле коры"],correctIndex:2,explanation:"Центральный отдел обонятельного анализатора — нижняя поверхность височной доли коры больших полушарий.",difficulty:"hard",tags:["обоняние","кора мозга"]},{id:"analyzers-052",topicId:"analyzers",question:"Где лежат обонятельные рецепторы?",options:["В эпителии слизистой оболочки носовой полости","В коже лица","В слизистой оболочке гортани","В слизистой оболочке языка"],correctIndex:0,explanation:"Обонятельные рецепторы лежат в эпителии слизистой оболочки носовой полости.",difficulty:"medium",tags:["обоняние","рецепторы"]},{id:"analyzers-053",topicId:"analyzers",question:"Как возникает нервный импульс в обонятельных рецепторах?",options:["Свет воздействует на пигмент родопсин","Изменяется давление отолитов","Молекулы пахучих веществ, растворяясь в секрете обонятельных желёз, взаимодействуют с рецепторными белками ресничек","Звуковые волны раздражают волосковые клетки"],correctIndex:2,explanation:"Молекулы пахучих веществ растворяются в секрете обонятельных желёз и взаимодействуют с рецепторными белками ресничек, что вызывает нервный импульс.",difficulty:"hard",tags:["обоняние","физиология"]},{id:"analyzers-054",topicId:"analyzers",question:"Сколько основных вкусов различает человек согласно лекции?",options:["6","5","4","3"],correctIndex:2,explanation:"Человек различает 4 основных вкуса: сладкое, кислое, горькое и солёное.",difficulty:"easy",tags:["вкус"]},{id:"analyzers-055",topicId:"analyzers",question:"Какой частью языка, согласно схеме лекции, воспринимается сладкий вкус?",options:["Средней частью","Корнем языка","Только краями языка","Кончиком языка"],correctIndex:3,explanation:"По схеме лекции сладкое воспринимается кончиком языка.",difficulty:"medium",tags:["вкус"]},{id:"analyzers-056",topicId:"analyzers",question:"Где на языке, по схеме лекции, ощущается горечь?",options:["Нижней поверхностью","Корнем языка","Кончиком языка","Краем языка"],correctIndex:1,explanation:"По схеме лекции горькое воспринимается корнем языка.",difficulty:"medium",tags:["вкус"]},{id:"analyzers-057",topicId:"analyzers",question:"Какие образования языка воспринимают вкусовые раздражители?",options:["Височная доля коры","Лицевой нерв","Вкусовые почки (вкусовые луковицы)","Сосочки носовой полости"],correctIndex:2,explanation:"Периферический отдел вкусового анализатора — вкусовые почки (вкусовые луковицы).",difficulty:"medium",tags:["вкус","отделы"]},{id:"analyzers-058",topicId:"analyzers",question:"Какие нервы являются проводниковым отделом вкусового анализатора?",options:["Подъязычный и добавочный","Лицевой и языкоглоточный","Зрительный и глазодвигательный","Тройничный и блуждающий"],correctIndex:1,explanation:"Проводниковый отдел вкусового анализатора — лицевой и языкоглоточный нерв.",difficulty:"hard",tags:["вкус","нервы"]},{id:"analyzers-059",topicId:"analyzers",question:"В какую долю коры в итоге поступают сигналы от рецепторов кожи?",options:["В лобной доле","В височной доле","В затылочной доле","В теменной доле больших полушарий"],correctIndex:3,explanation:"Центральный отдел кожного анализатора — теменная доля больших полушарий.",difficulty:"medium",tags:["кожный анализатор","кора мозга"]},{id:"analyzers-060",topicId:"analyzers",question:"Какие нервы составляют проводниковый отдел кожного анализатора?",options:["Зрительный и обонятельный нервы","Преддверно-улитковый нерв","Лицевой и языкоглоточный нервы","Тройничный нерв и спинномозговые нервы"],correctIndex:3,explanation:"Проводниковый отдел кожного анализатора — тройничный нерв и спинномозговые нервы.",difficulty:"hard",tags:["кожный анализатор","нервы"]},{id:"analyzers-061",topicId:"analyzers",question:"Через какую структуру импульс от кожных рецепторов идёт перед попаданием в кору?",options:["Через гипофиз","Через эпифиз","Через мозжечок","Через таламус"],correctIndex:3,explanation:"Нервный импульс от кожных рецепторов идёт сначала в таламус, а из него — в теменную долю коры.",difficulty:"medium",tags:["кожный анализатор","проводящие пути"]},{id:"analyzers-062",topicId:"analyzers",question:"Какие виды рецепторов есть в коже?",options:["Палочки и колбочки","Волосковые клетки и отолиты","Только болевые и тепловые","Давления, прикосновения, холодовые, тепловые и болевые"],correctIndex:3,explanation:"В коже есть рецепторы давления, прикосновения, холодовые, тепловые и болевые.",difficulty:"easy",tags:["кожный анализатор","рецепторы"]},{id:"analyzers-063",topicId:"analyzers",question:"Какой возбудитель вызывает чесотку?",options:["Sarcoptes scabiei","Candida albicans","Staphylococcus aureus","Trichomonas vaginalis"],correctIndex:0,explanation:"Чесотка — заразное кожное заболевание, возбудителем которого является Sarcoptes scabiei.",difficulty:"medium",tags:["кожа","заболевания"]},{id:"analyzers-064",topicId:"analyzers",question:"Как можно заразиться чесоткой?",options:["При продолжительном контакте с заболевшим или его предметами быта","Только через кровь","Через укус комара","Только воздушно-капельным путём"],correctIndex:0,explanation:"Заразиться чесоткой можно при продолжительном контакте с заболевшим или при контакте с его предметами быта.",difficulty:"medium",tags:["кожа","заболевания"]},{id:"analyzers-065",topicId:"analyzers",question:"Что такое экзема?",options:["Закупорка сальных желёз с активностью бактерий","Помутнение хрусталика","Заразное заболевание, вызываемое клещом","Хроническое кожное заболевание с покраснением, зудом и воспалением кожи"],correctIndex:3,explanation:"Экзема — хроническое кожное заболевание, сопровождающееся покраснением, зудом и воспалением кожи.",difficulty:"medium",tags:["кожа","заболевания"]},{id:"analyzers-066",topicId:"analyzers",question:"Из-за чего возникает акне (угревая болезнь)?",options:["Из-за заражения клещом","Из-за закупорки сальных желёз и активности бактерий","Из-за повышения внутриглазного давления","Из-за дефицита витамина D"],correctIndex:1,explanation:"Акне — хроническое воспалительное заболевание кожи, возникающее из-за закупорки сальных желёз и активности бактерий; поражает лицо, спину и грудь.",difficulty:"medium",tags:["кожа","заболевания"]},{id:"analyzers-067",topicId:"analyzers",question:"Какой препарат указан в таблице препаратов при отите?",options:["Бринзоламид","Софрадекс","Непафенак","Кетотифен"],correctIndex:1,explanation:"В таблице препаратов при отите указаны: рифамицин, неомицин + гидрокортизон + лидокаин, феназон + лидокаин, Софрадекс, Отинум, Отопрофен; бринзоламид, кетотифен и непафенак — глазные препараты.",difficulty:"medium",tags:["препараты","торговые названия"]},{id:"analyzers-068",topicId:"analyzers",question:"При каком заболевании применяются Отинум и Отопрофен по данным лекции?",options:["При катаракте","При отите","При экземе","При глаукоме"],correctIndex:1,explanation:"Отинум и Отопрофен перечислены в таблице «Препараты при отите».",difficulty:"easy",tags:["препараты","торговые названия"]}];export{a as default};
